<?php if(!$t): ?><div class="card"><div class="card-head"><h2>Yeni Şampiyona / Turnuva</h2></div><form method="post" class="form"><?= csrf_field() ?><input type="hidden" name="islem" value="turnuva_olustur"><div class="grid-2"><label>Turnuva adı *<input name="turnuva_adi" required placeholder="Geleneksel Okçuluk Türkiye Şampiyonası"></label><label>Tür *<select name="tur"><option value="takim">Takım Turnuvası</option><option value="bireysel">Bireysel Turnuva</option></select></label></div><div class="grid-2"><label>Katılımcı sayısı *<select name="kontenjan"><option value="16">16 katılımcı</option><option value="32">32 katılımcı</option></select></label><label>Sezon *<select name="sezon_id"><?php foreach($sezonlar as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['sezon_adi']) ?></option><?php endforeach; ?></select></label></div><label>Açıklama<textarea name="aciklama"></textarea></label><button class="btn btn-primary">Turnuva Oluştur</button></form></div><?php endif; ?>
<?php if($t): ?><div class="card"><div class="card-head"><h2><?= e($t['turnuva_adi']) ?></h2><span class="badge"><?= $t['tur']==='takim'?'Takım':'Bireysel' ?> · <?= (int)$t['kontenjan'] ?> kişi/takım</span></div><?php if($t['durum']==='taslak'): ?><form method="post" class="form"><?= csrf_field() ?><input type="hidden" name="islem" value="katilimcilari_kaydet"><input type="hidden" name="turnuva_id" value="<?= $id ?>"><p class="muted">Katılımcıları A, B, C, D… sırasıyla yerleştirin. İlk tur otomatik olarak A–C ve B–D biçiminde kurulur.</p><div class="grid-2"><?php for($i=0;$i<(int)$t['kontenjan'];$i++): ?><label><?= chr(65+($i%26)).($i>=26?floor($i/26):'') ?><select name="katilimci[]" required><option value="">Seçin</option><?php foreach($adaylar as $a): ?><option value="<?= (int)$a['id'] ?>" <?= (int)($katilimcilar[$i]['hedef_id']??0)===(int)$a['id']?'selected':'' ?>><?= e($a['ad']) ?></option><?php endforeach; ?></select></label><?php endfor; ?></div><button class="btn btn-primary">Katılımcıları Kaydet</button></form><?php if(count($katilimcilar)==(int)$t['kontenjan']): ?><form method="post" class="form" onsubmit="return confirm('İlk tur eşleşmeleri oluşturulsun mu?')"><?= csrf_field() ?><input type="hidden" name="islem" value="eslesme_olustur"><input type="hidden" name="turnuva_id" value="<?= $id ?>"><button class="btn btn-primary">A–C / B–D Eşleşmelerini Oluştur</button></form><?php endif; ?><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Tur</th><th>Eşleşme</th><th>Katılımcı 1</th><th>Katılımcı 2</th></tr></thead><tbody><?php foreach($eslesmeler as $e): ?><tr><td><?= (int)$e['tur_no'] ?>. Tur</td><td><?= (int)$e['eslesme_no'] ?></td><td><?= e($e['s1']) ?></td><td><?= e($e['s2']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><?php endif; ?>
<div class="table-wrap"><table class="data-table"><thead><tr><th>Turnuva</th><th>Tür</th><th>Sezon</th><th>Katılımcı</th><th>Durum</th><th></th></tr></thead><tbody><?php foreach($liste as $x): ?><tr><td><?= e($x['turnuva_adi']) ?></td><td><?= $x['tur']==='takim'?'Takım':'Bireysel' ?></td><td><?= e($x['sezon_adi']) ?></td><td><?= (int)$x['katilimci'].' / '.(int)$x['kontenjan'] ?></td><td><?= e($x['durum']) ?></td><td><a class="btn btn-sm" href="?id=<?= (int)$x['id'] ?>">Yönet</a></td></tr><?php endforeach; ?></tbody></table></div>
